<?php
namespace App\Services\Warehouse;
use App\Models\Outlet; use App\Models\User; use Illuminate\Http\Request; use Illuminate\Validation\ValidationException;
class WarehouseReceivingOutletTypeScopeResolver {
 public function resolve(Request $request): array { /** @var User $user */ $user=$request->user(); $user->loadMissing(['outlet','employee.assignment.outlet','accessAssignment.role']); $role=strtoupper(trim((string)($user->accessAssignment?->role?->code??''))); $isAdmin=$role==='ADMIN'||$user->hasAnyRole(['admin','administrator','superadmin','super-admin']); $home=$user->employee?->assignment?->outlet ?: $user->outlet; $requestedId=trim((string)$request->header('X-Outlet-Id',$request->query('outlet_id',''))); if(!$home&&!$isAdmin) throw ValidationException::withMessages(['outlet_id'=>['Akun tidak mempunyai outlet assignment aktif.']]); $selected=$requestedId!==''?Outlet::query()->whereKey($requestedId)->where('is_active',true)->first():$home; if(!$selected) throw ValidationException::withMessages(['outlet_id'=>['Outlet receiving tidak ditemukan.']]); if(!$isAdmin){$allowed=in_array($role,['SPV','SQUAD'],true)||$user->hasAnyRole(['spv','squad']); if(!$allowed) throw ValidationException::withMessages(['outlet_id'=>['Receiving hanya dapat dilakukan Squad atau SPV yang memiliki permission.']]); if(strtolower(trim((string)$home?->type))!==strtolower(trim((string)$selected->type))) throw ValidationException::withMessages(['outlet_id'=>['Receiving hanya dapat dilakukan untuk outlet dengan tipe yang sama dengan outlet assignment akun.']]);} return ['selected'=>$selected,'scope_locked'=>!$isAdmin,'can_adjust_scope'=>true,'outlet_type'=>(string)$selected->type]; }
}
